var t = get_tree().get_first_node_in_group('terrain')
var p = get_tree().get_first_node_in_group('player')
var vis = get_tree().get_first_node_in_group('visibility_overlay')
var l = get_tree().get_first_node_in_group('lantern')
var out = {}
if t:
	out.t_visible = t.visible
	out.t_mod = str(t.modulate)
	out.t_pos = t.global_position
	out.t_z = t.z_index
	out.cell_400_72 = t.get_cell_source_id(Vector2i(400, 72))
	out.cell_400_71 = t.get_cell_source_id(Vector2i(400, 71))
	out.cell_405_72 = t.get_cell_source_id(Vector2i(405, 72))
if p:
	out.p_visible = p.visible
	out.p_mod = str(p.modulate)
	out.p_z = p.z_index
	out.p_self = p.visible
if vis:
	out.v_visible = vis.visible
	out.v_mod = str(vis.modulate)
	out.v_z = vis.z_index
	out.v_has_tex = vis.texture != null
	if vis.texture:
		out.v_tex_size = vis.texture.get_size()
	out.v_pos = vis.global_position
if l:
	out.l_visible = l.visible
	out.l_z = l.z_index
	var spr = l.get_node_or_null('Visuals/BaseSprite')
	if spr:
		out.spr_tex = spr.texture != null
		out.spr_scale = spr.scale
		out.spr_pos = spr.global_position
return out
